# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use a safety-gated finite-state controller with target confirmation,
    hysteretic reacquisition, and bearing/heading-aware corridor steering.
    """
    old = memory if isinstance(memory, dict) else {}
    state = old.get("state", "IDLE")
    scan_direction = old.get("scan_direction", "SCAN_LEFT")
    search_phase = int(old.get("search_phase", 0))
    lock_streak = int(old.get("lock_streak", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = float(observation["heading_error"])

    def pack(next_state, direction=scan_direction, phase=search_phase, streak=lock_streak):
        return {
            "state": next_state,
            "scan_direction": direction,
            "search_phase": int(max(0, min(8, phase))),
            "lock_streak": int(max(0, min(8, streak))),
        }

    # Safety is an unconditional hard gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return "STOP", 0.99, pack("STOPPED", streak=0)

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        phase = search_phase + 1
        # Briefly hold after loss, then scan with a stable direction.  Reverse
        # only after a complete short sweep, reducing oscillatory instructions.
        if lost_steps <= 1:
            return "STOP", 0.92, pack("REACQUIRE", phase=phase, streak=0)
        if phase >= 3:
            direction = "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            phase = 0
        else:
            direction = scan_direction
        return direction, 0.75, pack("SEARCH", direction, phase, 0)

    # Require a short stable track before committing to motion.
    streak = min(8, lock_streak + 1)
    if track_age < 2 or streak < 2:
        return "SLOW_DOWN", 0.80, pack("VERIFY", streak=streak)

    # Arrival requires proximity, alignment, and persistent identity.
    if (
        distance == "near"
        and abs(heading_error) <= 15.0
        and abs(bearing) <= 15.0
        and identity_confidence >= 0.80
    ):
        return "ARRIVED", 0.96, pack("ARRIVED", streak=streak)

    # Blend visual bearing and heading error for steadier, target-driven turns.
    error = 0.60 * bearing + 0.40 * heading_error
    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    if error < -12.0 and left:
        return "VEER_LEFT", 0.90, pack("APPROACH", streak=streak)
    if error > 12.0 and right:
        return "VEER_RIGHT", 0.90, pack("APPROACH", streak=streak)
    if center and abs(error) <= 12.0:
        return "FORWARD", 0.90, pack("APPROACH", streak=streak)
    if error < 0.0 and left:
        return "VEER_LEFT", 0.82, pack("APPROACH", streak=streak)
    if error > 0.0 and right:
        return "VEER_RIGHT", 0.82, pack("APPROACH", streak=streak)
    if center:
        return "FORWARD", 0.78, pack("APPROACH", streak=streak)
    if left:
        return "VEER_LEFT", 0.78, pack("APPROACH", streak=streak)
    if right:
        return "VEER_RIGHT", 0.78, pack("APPROACH", streak=streak)

    return "STOP", 0.98, pack("STOPPED", streak=0)
# EVOLVE-BLOCK-END
